import Foundation

/// One `focuspilot report` (#67, decision 0004, Phase 2 start), as a helper
/// agent sends it or the inbox queues it: a plain summary, the project, and
/// optionally the exact message to send to a named Herdr agent.
public struct ReportRequest: Codable, Equatable, Sendable {
    /// Generated by the CLI; the same report is never stored twice.
    public var id: UUID
    public var summary: String
    /// A project title; without it, the project linked to the caller's workspace.
    public var project: String?
    /// The agent to send the message to: a pane ID ("w4:p2") or an agent name.
    public var to: String?
    /// The exact text Accept sends.
    public var message: String?
    /// The reporting agent's name, if it gives one.
    public var from: String?
    public var sentAt: Date
    public var caller: HerdrCaller?

    public init(id: UUID = UUID(), summary: String, project: String?, to: String?, message: String?, from: String?,
                sentAt: Date, caller: HerdrCaller?) {
        self.id = id
        self.summary = summary
        self.project = project
        self.to = to
        self.message = message
        self.from = from
        self.sentAt = sentAt
        self.caller = caller
    }

    /// Why the report is refused, if it is. Nothing is changed to fit.
    public var problem: String? {
        if let problem = ReportRules.summaryProblem(summary) { return problem }
        if let project, let problem = ReportRules.nameProblem(project, what: "project name") { return problem }
        if let from, let problem = ReportRules.nameProblem(from, what: "--from name") { return problem }
        switch (to, message) {
        case (nil, nil): return nil
        case (nil, _?): return "A proposed message needs --to, the Herdr agent to send it to."
        case (_?, nil): return "--to needs --message, the exact text to send."
        case (let to?, let message?):
            return ReportRules.nameProblem(to, what: "--to agent") ?? ReportRules.messageProblem(message)
        }
    }
}

/// The agent a proposal is for, as it was when the report arrived: like a
/// linked agent (S4), it is the same server instance, pane and program, and
/// the same name if it had one.
public struct ReportTarget: Codable, Equatable, Sendable {
    public var server: HerdrServer
    public var paneID: String
    public var name: String?
    public var kind: String

    public init(server: HerdrServer, paneID: String, name: String?, kind: String) {
        self.server = server
        self.paneID = paneID
        self.name = name
        self.kind = kind
    }

    public var label: String { name ?? paneID }

    /// The agent `given` names among Herdr's current agents: its pane ID, or
    /// its exact name if exactly one agent has it.
    static func resolve(_ given: String, in agents: HerdrAgents, caller: HerdrCaller?) -> Result<ReportTarget, ReportTargetProblem> {
        guard case .connected(let server, let list) = agents else { return .failure(.herdrUnavailable) }
        if let caller, caller.server != server { return .failure(.otherServer) }
        let matches = list.contains { $0.paneID == given } ? list.filter { $0.paneID == given } : list.filter { $0.name == given }
        guard let found = matches.first else { return .failure(.notFound(given)) }
        guard matches.count == 1 else { return .failure(.ambiguous(given, example: found.paneID)) }
        return .success(ReportTarget(server: server, paneID: found.paneID, name: found.name, kind: found.kind))
    }

    /// Whether the agent can be sent to now: still there, the same, and not
    /// waiting for an approval (a prompt would answer it).
    func check(in agents: HerdrAgents) -> Result<HerdrAgent, AcceptRefusal> {
        guard case .connected(let current, let list) = agents else { return .failure(.herdrUnavailable) }
        guard current == server, let agent = list.first(where: { $0.paneID == paneID }) else { return .failure(.gone(name: label)) }
        guard agent.kind == kind else { return .failure(.replaced(name: label)) }
        if let name, agent.name != name { return .failure(.renamed(from: name, to: agent.name ?? agent.kind)) }
        if agent.status == .blocked { return .failure(.blocked(name: label)) }
        return .success(agent)
    }
}

/// Why a proposal has no target to send to.
public enum ReportTargetProblem: Error, Equatable, Sendable {
    case notFound(String)
    case ambiguous(String, example: String)
    case otherServer
    case herdrUnavailable

    public var text: String {
        switch self {
        case .notFound(let given): "FocusPilot couldn’t find an agent named “\(given)” in Herdr when the report arrived."
        case .ambiguous(let given, let example):
            "More than one agent in Herdr is named “\(given)”. Ask for the report again with the pane ID, such as \(example)."
        case .otherServer: "The report came from a Herdr session that is no longer running, so its target can’t be trusted."
        case .herdrUnavailable: "Herdr wasn’t reachable when the report arrived, so its target couldn’t be checked."
        }
    }
}

/// A report waiting for the owner.
public struct AgentReport: Equatable, Sendable, Identifiable {
    public var id: Int64
    public var clientID: UUID
    public var summary: String
    public var projectID: Int64?
    public var projectTitle: String?
    /// "second", "Bowling reviewer", or the pane when nothing else is known.
    public var sourceLabel: String
    public var proposal: ReportProposal?
    public var receivedAt: Date
}

public struct ReportProposal: Equatable, Sendable {
    /// Exactly what Accept sends.
    public var message: String
    /// The agent as given in `--to`.
    public var targetAsGiven: String
    /// Nil when it could not be resolved; `targetProblem` says why.
    public var target: ReportTarget?
    public var targetProblem: String?
}

/// What storing a report did, for the CLI's reply.
public struct ReportReceipt: Codable, Equatable, Sendable {
    public var wasAlreadyReceived: Bool
    public var projectTitle: String?
    /// Why the proposal cannot be accepted as it stands, if it cannot.
    public var targetProblem: String?
    /// A note, e.g. that no project has the name given.
    public var notes: [String]

    public init(wasAlreadyReceived: Bool, projectTitle: String?, targetProblem: String?, notes: [String] = []) {
        self.wasAlreadyReceived = wasAlreadyReceived
        self.projectTitle = projectTitle
        self.targetProblem = targetProblem
        self.notes = notes
    }
}

/// What Accept did.
public enum AcceptOutcome: Equatable, Sendable {
    case sent(to: String)
    case notSent(AcceptRefusal)
}

/// Why Accept sent nothing.
public enum AcceptRefusal: Error, Equatable, Sendable {
    case gone(name: String)
    case renamed(from: String, to: String)
    case replaced(name: String)
    case blocked(name: String)
    case herdrUnavailable
    /// The proposal never had a target that could be checked.
    case noTarget
    /// What the owner saw is not what is stored.
    case changed
    /// Already sent or dismissed.
    case alreadyHandled
    case failed

    /// Plain words for the attention row: what happened and what to do.
    public var text: String {
        switch self {
        case .gone(let name): "Not sent. \(name) isn’t in Herdr anymore, or Herdr restarted. Dismiss this report, or ask for a new one."
        case .renamed(let old, let new): "Not sent. The agent \(old) is now named “\(new)” in Herdr. Check it’s the same agent, then ask for a new report."
        case .replaced(let name): "Not sent. A different program is running in \(name)’s pane now."
        case .blocked(let name): "Not sent. \(name) is waiting for an approval in Herdr. Answer it there first, then accept again."
        case .herdrUnavailable: "Not sent. Herdr isn’t reachable right now. Try again when it’s running."
        case .noTarget: "Not sent. This proposal has no agent that FocusPilot could check."
        case .changed: "Not sent. The report changed after it was shown. Look at it again before accepting."
        case .alreadyHandled: "This report was already handled."
        case .failed: "Not sent. Herdr didn’t accept the message. Nothing was changed."
        }
    }
}

/// A report that breaks `ReportRules`; it is never stored.
public struct ReportRefused: Error, Equatable {
    public var reason: String
}
